const request = request1;
const url = env.get("Endpoint")|| '';
const buffer_msg = msg.payload;
msg.info = "";

function post_msg(payload){
  var options = {
    'method': 'POST',
    'url': url,
    'headers': {
      'Content-Type': 'application/json'
    },
    'rejectUnauthorized': false,
    body: JSON.stringify(payload),
    timeout: 30000 // Timeout of 30 seconds

  };
  request(options, function (error, response) {
    if (error) {
      node.status({ fill: "red", shape: "ring", text: `Connection error...` });    
      msg.payload = [];
      node.send(msg);
    } else if (response.statusCode == 200) { // success
      node.status({ fill: "blue", shape: "dot", text: `Message Post Success, StatusCode: ${response.statusCode}` });
      msg.payload = [payload];
      msg.info = "sent.";
      node.send(msg)
    }else{
      node.status({ fill: "yellow", shape: "ring", text: `Message Post Failed, StatusCode: ${response.statusCode}` });
      msg.payload = [];
      node.send(msg)
    }
  });
}

