let now = new Date().toISOString();

function rand(min, max, decimals = 2) {
    return +((Math.random() * (max - min) + min).toFixed(decimals));
}

// Chiller system
let chiller = {
    energy_kWh: rand(12, 20),
    load_percent: rand(65, 100),
    COP: rand(2.5, 4.5),
    flow_rate_lps: rand(30, 60)
};

// Lighting system
let lighting = {
    energy_kWh: rand(3, 7),
    zone_usage: rand(50, 100),
    power_factor: rand(0.85, 1.0)
};

// Elevator
let elevator = {
    energy_kWh: rand(1, 3),
    trip_count: Math.floor(rand(5, 20)),
    idle_time_min: rand(5, 30)
};

// Diesel Generator
let genset = {
    energy_kWh: rand(0, 6),
    fuel_liters: rand(0, 2),
    efficiency_kWh_per_l: rand(2, 3)
};

// Fire Alarm
let fire_alarm = {
    energy_kWh: rand(0.3, 0.8),
    alarm_triggered: Math.random() < 0.1,
    standby_power_W: rand(10, 25)
};

// Solar generation
let hour = new Date().getHours();
let irradiance = (hour >= 6 && hour <= 18) ? rand(400, 1000) : 0;
let solar_kWh = irradiance ? rand(5, 15) : 0;
let solar = {
    generated_kWh: solar_kWh,
    irradiance_Wm2: irradiance,
    efficiency_percent: rand(15, 20)
};

// Total demand
let total_kWh = chiller.energy_kWh + lighting.energy_kWh + elevator.energy_kWh + genset.energy_kWh + fire_alarm.energy_kWh;

// Grid supply
let grid_kWh = +(Math.max(0, total_kWh - solar.generated_kWh).toFixed(2));
let tariff = 7.2;
let grid = {
    consumed_kWh: grid_kWh,
    tariff_INR_kWh: tariff,
    cost_INR: +(grid_kWh * tariff).toFixed(2)
};

msg.payload = {
    timestamp: now,
    chiller,
    lighting,
    elevator,
    genset,
    fire_alarm,
    solar,
    grid
};

return msg;
